{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello राज जी आपको कमसूत्रा capsules की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "आपको कितने pieces चाहिए?"
    },
    {
      "i": 4,
      "speaker": "caller",
      "text": "को call करें।"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "एक वचन।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "क्या आपको एक bottle चाहिए?"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "नहीं।"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "जी यहाँ को चाहिए।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "मैं देख पा रही हूं कि आपको pack size 30 capsules ही चाहिए ना?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "अब बताइए therapeutic use में क्या prefer करेंगे performance enhancement, timing increase या कोई और?"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "तो time चाहिए मतलब?"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "ये आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "Hello."
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "जी मैं यही हूँ।"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "क्या"
    },
    {
      "i": 20,
      "speaker": "caller",
      "text": "किंतु ये दवा कितनी मात्रा में पड़ता है?"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "कम।"
    }
  ]
}
